"use client";
import { useEffect, useState } from "react";
import { api } from "./api";
import { Button, Card, Field, inputClass, Notice } from "./ui";

const DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const TYPES: { id: string; label: string; unit: string; units: string; seats: string }[] = [
  { id: "restaurant", label: "Restaurant or café", unit: "table", units: "Tables", seats: "Seats" },
  { id: "salon", label: "Salon or barber", unit: "stylist", units: "Stylists", seats: "Clients at once" },
  { id: "clinic", label: "Clinic or practice", unit: "practitioner", units: "Practitioners", seats: "Patients at once" },
  { id: "hotel", label: "Hotel or rooms", unit: "room", units: "Rooms", seats: "Guests per room" },
  { id: "repair", label: "Repair or service", unit: "technician", units: "Technicians", seats: "Jobs at once" },
  { id: "other", label: "Something else", unit: "slot", units: "Slots", seats: "People per slot" },
];
const STEPS = ["Business", "Opening hours", "Capacity", "Assistant"];

type Row = { capacity: number; count: number };

export function SetupWizard() {
  const [step, setStep] = useState(0);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  // The browser's own list is read after the page has hydrated: the server's list can differ, and
  // rendering either one on both sides would make the first client render disagree with the server.
  const [zones, setZones] = useState<string[]>(["UTC"]);

  const [profile, setProfile] = useState({ name: "", type: "restaurant", timezone: "UTC", address: "", phone: "", contact_email: "" });
  const [hours, setHours] = useState(DAYS.map(() => ({ open: true, from: "12:00", to: "22:00" })));
  const [rows, setRows] = useState<Row[]>([{ capacity: 2, count: 4 }, { capacity: 4, count: 4 }, { capacity: 6, count: 2 }]);
  const [rules, setRules] = useState({ default_duration_min: 90, slot_interval_min: 30, max_party_size: 6 });
  const [agent, setAgent] = useState({ name: "Robin", tone: "friendly and concise", languages: "English", greeting: "" });

  useEffect(() => { try { setZones(Intl.supportedValuesOf("timeZone")); } catch {} }, []);
  useEffect(() => { try { setProfile((p) => ({ ...p, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC" })); } catch {} }, []);
  const type = TYPES.find((t) => t.id === profile.type)!;

  function chooseType(id: string) {
    setProfile((p) => ({ ...p, type: id }));
    if (id === "restaurant") { setRows([{ capacity: 2, count: 4 }, { capacity: 4, count: 4 }, { capacity: 6, count: 2 }]); setRules({ default_duration_min: 90, slot_interval_min: 30, max_party_size: 6 }); setHours(DAYS.map(() => ({ open: true, from: "12:00", to: "22:00" }))); }
    else { setRows([{ capacity: 1, count: 2 }]); setRules({ default_duration_min: id === "hotel" ? 60 : 45, slot_interval_min: 15, max_party_size: 1 }); setHours(DAYS.map((_, i) => ({ open: i < 6, from: "09:00", to: "18:00" }))); }
  }

  function validate(): string {
    if (step === 0 && profile.name.trim().length < 2) return "Enter your business name.";
    if (step === 1) {
      if (!hours.some((h) => h.open)) return "Choose at least one day you are open.";
      if (hours.some((h) => h.open && h.to <= h.from)) return "Closing time must be after opening time.";
    }
    if (step === 2 && rows.some((r) => !(r.capacity >= 1) || !(r.count >= 1))) return "Each row needs at least 1.";
    return "";
  }

  async function finish() {
    setBusy(true); setError("");
    try {
      const largest = Math.max(...rows.map((r) => r.capacity));
      const r = await api<{ business: { slug: string } }>("/api/businesses", {
        body: {
          ...profile,
          hours: hours.flatMap((h, i) => (h.open ? [{ weekday: i + 1, open: h.from, close: h.to }] : [])),
          capacity: rows.map((r) => ({ capacity: Number(r.capacity), count: Number(r.count) })),
          policies: { ...rules, max_party_size: Math.min(rules.max_party_size, largest) },
          agent: {
            name: agent.name || "Assistant", tone: agent.tone,
            languages: agent.languages.split(",").map((s) => s.trim()).filter(Boolean),
            greeting: agent.greeting || `Hi! I'm ${agent.name || "the assistant"}. I can help you book at ${profile.name}. When would you like to come?`,
          },
        },
      });
      window.location.assign(`/app/${r.business.slug}?welcome=1`);
    } catch (e) { setError((e as Error).message); setBusy(false); }
  }

  function next() {
    const v = validate();
    setError(v);
    if (v) return;
    if (step < STEPS.length - 1) setStep(step + 1); else void finish();
  }

  const num = (v: string) => Math.max(0, Math.floor(Number(v) || 0));

  return (
    <Card className="p-6">
      <ol className="mb-6 flex gap-2" aria-label="Setup progress">
        {STEPS.map((s, i) => (
          <li key={s} aria-current={i === step ? "step" : undefined} className="flex-1">
            <div className={`h-1.5 rounded-full ${i <= step ? "bg-brand" : "bg-line"}`} />
            <span className={`mt-1.5 block text-[13px] font-semibold ${i === step ? "text-ink" : "text-muted"}`}>{i + 1}. {s}</span>
          </li>
        ))}
      </ol>

      {step === 0 && (
        <div className="space-y-4">
          <Field label="Business name"><input className={inputClass} value={profile.name} onChange={(e) => setProfile({ ...profile, name: e.target.value })} maxLength={80} autoFocus /></Field>
          <Field label="What kind of business?">
            <select className={inputClass} value={profile.type} onChange={(e) => chooseType(e.target.value)}>
              {TYPES.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}
            </select>
          </Field>
          <Field label="Time zone" hint="Reservation times are shown in this time zone.">
            <select className={inputClass} value={profile.timezone} onChange={(e) => setProfile({ ...profile, timezone: e.target.value })}>
              {!zones.includes(profile.timezone) && <option>{profile.timezone}</option>}
              {zones.map((z) => <option key={z}>{z}</option>)}
            </select>
          </Field>
          <div className="grid gap-4 sm:grid-cols-2">
            <Field label="Address"><input className={inputClass} value={profile.address} onChange={(e) => setProfile({ ...profile, address: e.target.value })} maxLength={200} /></Field>
            <Field label="Phone"><input className={inputClass} value={profile.phone} onChange={(e) => setProfile({ ...profile, phone: e.target.value })} maxLength={40} /></Field>
          </div>
        </div>
      )}

      {step === 1 && (
        <div className="space-y-2">
          {DAYS.map((d, i) => (
            <div key={d} className="flex items-center gap-3">
              <label className="flex w-36 items-center gap-2 font-semibold">
                <input type="checkbox" className="size-5 accent-[var(--color-brand)]" checked={hours[i].open} onChange={(e) => setHours(hours.map((h, j) => (j === i ? { ...h, open: e.target.checked } : h)))} />
                {d}
              </label>
              {hours[i].open ? (
                <>
                  <input aria-label={`${d} opens`} type="time" className={`${inputClass} w-32`} value={hours[i].from} onChange={(e) => setHours(hours.map((h, j) => (j === i ? { ...h, from: e.target.value } : h)))} />
                  <span className="text-muted">to</span>
                  <input aria-label={`${d} closes`} type="time" className={`${inputClass} w-32`} value={hours[i].to} onChange={(e) => setHours(hours.map((h, j) => (j === i ? { ...h, to: e.target.value } : h)))} />
                </>
              ) : <span className="text-muted">Closed</span>}
            </div>
          ))}
          <p className="pt-2 text-[13px] text-muted">Split hours (lunch and dinner), holidays and closures can be added in Settings.</p>
        </div>
      )}

      {step === 2 && (
        <div className="space-y-5">
          <div>
            <p className="mb-2 font-semibold">{type.units}</p>
            <div className="space-y-2">
              {rows.map((r, i) => (
                <div key={i} className="flex items-end gap-3">
                  <Field label="How many" className="w-28"><input type="number" min={1} max={100} className={inputClass} value={r.count} onChange={(e) => setRows(rows.map((x, j) => (j === i ? { ...x, count: num(e.target.value) } : x)))} /></Field>
                  <Field label={type.seats} className="w-36"><input type="number" min={1} max={500} className={inputClass} value={r.capacity} onChange={(e) => setRows(rows.map((x, j) => (j === i ? { ...x, capacity: num(e.target.value) } : x)))} /></Field>
                  {rows.length > 1 && <Button variant="quiet" type="button" onClick={() => setRows(rows.filter((_, j) => j !== i))}>Remove</Button>}
                </div>
              ))}
            </div>
            <Button variant="quiet" type="button" className="mt-3" onClick={() => setRows([...rows, { capacity: 4, count: 1 }])}>Add another size</Button>
          </div>
          <div className="grid gap-4 sm:grid-cols-3">
            <Field label="Booking length (min)"><input type="number" min={5} max={1440} className={inputClass} value={rules.default_duration_min} onChange={(e) => setRules({ ...rules, default_duration_min: num(e.target.value) })} /></Field>
            <Field label="Times every (min)"><input type="number" min={5} max={240} className={inputClass} value={rules.slot_interval_min} onChange={(e) => setRules({ ...rules, slot_interval_min: num(e.target.value) })} /></Field>
            <Field label="Largest online booking"><input type="number" min={1} max={500} className={inputClass} value={rules.max_party_size} onChange={(e) => setRules({ ...rules, max_party_size: num(e.target.value) })} /></Field>
          </div>
        </div>
      )}

      {step === 3 && (
        <div className="space-y-4">
          <Field label="Assistant's name"><input className={inputClass} value={agent.name} onChange={(e) => setAgent({ ...agent, name: e.target.value })} maxLength={40} /></Field>
          <Field label="Tone">
            <select className={inputClass} value={agent.tone} onChange={(e) => setAgent({ ...agent, tone: e.target.value })}>
              <option>friendly and concise</option><option>warm and welcoming</option><option>formal and polite</option><option>relaxed and casual</option>
            </select>
          </Field>
          <Field label="Languages" hint="Separate with commas. The first is the default."><input className={inputClass} value={agent.languages} onChange={(e) => setAgent({ ...agent, languages: e.target.value })} /></Field>
          <Field label="Greeting" hint="Leave empty for a standard greeting."><input className={inputClass} value={agent.greeting} onChange={(e) => setAgent({ ...agent, greeting: e.target.value })} maxLength={300} /></Field>
        </div>
      )}

      {error && <div className="mt-4"><Notice tone="error">{error}</Notice></div>}
      <div className="mt-6 flex justify-between">
        <Button variant="quiet" type="button" disabled={step === 0 || busy} onClick={() => { setError(""); setStep(step - 1); }}>Back</Button>
        <Button type="button" disabled={busy} onClick={next}>{step < STEPS.length - 1 ? "Continue" : busy ? "Creating…" : "Create business"}</Button>
      </div>
    </Card>
  );
}
